# Now apply the formula to test case
input_test = [2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 3, 8, 3, 3, 8, 8, 8, 8, 3, 3, 8, 8, 3, 8, 8]
N = 26
L = 11  # Leading 2s
output_rows = N // 2  # 13

output = []
for i in range(output_rows):
    zeros = [0] * (i + L)
    remain = input_test[i + L:]
    combined = zeros + remain
    if len(combined) > N:
        combined = combined[:N]
    output.append(combined)

# Verify and print first 5 rows and last 3 rows
print("Output grid:")
for i, row in enumerate(output):
    if i < 5 or i >= 10:
        print(f"Row {i}: {row}")
    elif i == 5:
        print(f"...")
        if i < 8:
            for j in range(i+1, min(i+4, len(output))):
                print(f"Row {j}: {output[j]}")

